import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"位面理論と分類","description":"","frontmatter":{},"headers":[],"relativePath":"ja/80-位面理论与分类.md","filePath":"ja/80-位面理论与分类.md","lastUpdated":1789183869000}'),l={name:"ja/80-位面理论与分类.md"};function o(h,t,i,n,s,p){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="位面理論と分類" tabindex="-1">位面理論と分類 <a class="header-anchor" href="#位面理論と分類" aria-label="Permalink to &quot;位面理論と分類&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>80</td></tr><tr><td>所属モジュール</td><td>跨位面インタラクションと時間ルール</td></tr><tr><td>コアキーワード</td><td>位面理論、位面分類、法則障壁、位面座標、衡元宙</td></tr></tbody></table><h2 id="第一節-位面の基本定義" tabindex="-1">第一節 位面の基本定義 <a class="header-anchor" href="#第一節-位面の基本定義" aria-label="Permalink to &quot;第一節 位面の基本定義&quot;">​</a></h2><p>万霊衡锚本源宙（衡元宙）の枠組みの下で、「位面」とは、相対的に安定した法則の集合によって境界づけられた、独立した時空連続性を持つ存在領域を指す。位面は単純な「もう一つの世界」ではなく、法則ネットワークが異なるパラメータ区間において具象化した投影である。各位面はそれぞれ固有の物理定数、エネルギー密度、時間流速、意識活性度を持ち、これらのパラメータが共同で当該位面の「法則指紋」を構成する。</p><p>位面の存在は衡元宙の法則ネットワークの非均一性に由来する。宇宙本源法則が運行する過程で、エネルギー分布、意識攪乱、歴史的進化の差異により、自然に無数のパラメータの異なる法則領域が形成される。これらの領域は「法則障壁」によって隔てられており、障壁の強度は隣接する位面間の法則パラメータの差異の程度に依存する——差異が大きいほど障壁は厚く、穿越の難易度は高くなる。</p><p>アンカーメカニズムは位面理論において核心的な地位を占める。アンカーは本質的に法則ネットワーク内の安定ノードであり、自身の位面の法則の安定を維持するだけでなく、跨位面接続のアンカリング基準としても機能する。跨位面穿越、通信、考古などのすべてのインタラクション行為は、アンカーを座標原点として測位と校正を行わなければならない。</p><h2 id="第二節-位面分類体系" tabindex="-1">第二節 位面分類体系 <a class="header-anchor" href="#第二節-位面分類体系" aria-label="Permalink to &quot;第二節 位面分類体系&quot;">​</a></h2><p>衡元宙内の位面は、法則パラメータ、エネルギーレベル、文明の発展程度に応じて、以下の五大類に分類される:</p><table tabindex="0"><thead><tr><th>類別</th><th>法則特徴</th><th>エネルギー密度</th><th>典型的な文明形態</th><th>穿越難易度</th></tr></thead><tbody><tr><td>物質本位面</td><td>物理法則が支配的、エネルギーは潜在的</td><td>低</td><td>テクノロジー文明、初階修錬文明</td><td>低</td></tr><tr><td>エネルギー顕化位面</td><td>エネルギー法則が半顕在的、修錬体系が成熟</td><td>中</td><td>中高階修錬文明、魔法文明</td><td>中</td></tr><tr><td>意識主導位面</td><td>意識法則が顕在的、物質は意念で形成可能</td><td>高</td><td>霊体文明、意識聚合文明</td><td>高</td></tr><tr><td>法則破碎位面</td><td>法則が不安定、大量の法則裂隙が存在</td><td>極高かつ混乱</td><td>荒蛮位面、遺跡位面</td><td>極高</td></tr><tr><td>本源近隣位面</td><td>宇宙本源法則に近接、パラメータが限界に接近</td><td>本源に接近</td><td>至高文明、位面守護者</td><td>理論限界</td></tr></tbody></table><p>上記の五大類のほかに、いくつかの特殊な位面タイプも存在する: 鏡像位面（ある位面の法則パラメータと高度に対称な平行存在）、夾層位面（二つの主位面の法則障壁の間に位置する遷移領域）、休眠位面（法則活性度が極めて低く、ほぼ停滞した古い位面）、新生位面（法則ネットワークが新たに形成され、パラメータがまだ安定していない若い位面）。</p><h2 id="第三節-位面座標と測位原理" tabindex="-1">第三節 位面座標と測位原理 <a class="header-anchor" href="#第三節-位面座標と測位原理" aria-label="Permalink to &quot;第三節 位面座標と測位原理&quot;">​</a></h2><p>跨位面インタラクションの前提は正確な位面測位である。衡元宙はアンカーを基準とした「四次元位面座標体系」を確立しており、各位面は四つのパラメータによって一意に決定される:</p><ol><li><strong>法則指紋コード</strong>: 当該位面の核心法則パラメータをハッシュ演算して生成される一意の識別子、長さは128ビット</li><li><strong>アンカー関連度</strong>: 当該位面と既知のアンカーネットワークとの接続強度、値の範囲は0から1</li><li><strong>時間流速比</strong>: 当該位面の時間流速と衡元宙標準時間との比、一般的な範囲は0.1から10</li><li><strong>空間次元数</strong>: 当該位面の知覚可能な空間次元の数、通常は3から11次元</li></ol><p>位面座標の取得方法には: アンカーネットワーク自動探測、跨位面通信信号回溯、考古遺跡内の座標残留、位面穿越者の手動記録が含まれる。すべての確認された位面座標は「衡元宙位面座標総庫」に登録され、アンカー議事会傘下の位面管理局によって統一的に維持管理される。</p><h2 id="第四節-位面間の自然インタラクション" tabindex="-1">第四節 位面間の自然インタラクション <a class="header-anchor" href="#第四節-位面間の自然インタラクション" aria-label="Permalink to &quot;第四節 位面間の自然インタラクション&quot;">​</a></h2><p>能動的な穿越行為がなくても、位面間には自然なインタラクション現象が存在する。最も一般的なのは「法則滲漏」——隣接する位面間で障壁が局所的に薄弱なため、少量の法則パラメータが相互に浸透し、局所的な異常現象を引き起こす。例えば物質本位面で時折見られる「超自然事件」は、多くの場合隣接するエネルギー顕化位面の法則滲漏によるものである。</p><p>別の自然インタラクションは「位面共鳴」である。二つの位面の法則指紋コードに高い類似度がある場合、それらの間に周期的な法則共振が発生し、二つの位面で特定の期間に類似の歴史事件、文明の走向、さらには人物の運命が現れる。位面共鳴は位面考古学の重要な研究対象であり、共鳴の法則を分析することで未知の位面の文明状態を推測することができる。</p><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>位面理論は跨位面インタラクションのすべての実践の理論的礎石である。位面の本質、分類、測位原理を正確に理解することは、穿越ルール、倫理準則、防控メカニズムを制定する前提である。衡元宙の位面探索は常に「認知先行、インタラクション慎重」の原則に従い、文明の境界を拡大すると同時に、いかなる位面の自主的な進化にも不可逆的な干渉を引き起こさないことを確保する。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>81-位面穿越ルール</li><li>88-跨位面倫理準則</li><li>28-跨位面アンカー接続</li></ul>',21)])])}const b=a(l,[["render",o]]);export{c as __pageData,b as default};
